"""A small in-memory warehouse inventory tracker.

Tracks stock counts for SKUs across named bins (locations). Stdlib-only,
no external dependencies -- intended as a compact, realistic example
codebase, not a toy one-liner.
"""

from __future__ import annotations

from dataclasses import dataclass, field


class InventoryError(Exception):
    """Raised for any invalid inventory operation."""


@dataclass
class Inventory:
    """Tracks SKU quantities across named bins.

    Internal representation: ``{sku: {bin_name: quantity}}``. Quantities
    are always non-negative integers; a bin with zero stock for a SKU is
    pruned rather than kept around as an explicit zero entry.
    """

    _stock: dict[str, dict[str, int]] = field(default_factory=dict)

    def add_stock(self, sku: str, bin_name: str, quantity: int) -> None:
        """Add ``quantity`` units of ``sku`` into ``bin_name``."""
        if quantity <= 0:
            raise InventoryError(f"quantity must be positive, got {quantity}")
        bins = self._stock.setdefault(sku, {})
        bins[bin_name] = bins.get(bin_name, 0) + quantity

    def remove_stock(self, sku: str, bin_name: str, quantity: int) -> None:
        """Remove ``quantity`` units of ``sku`` from ``bin_name``.

        Raises ``InventoryError`` if there isn't enough stock present.
        """
        if quantity <= 0:
            raise InventoryError(f"quantity must be positive, got {quantity}")
        available = self._stock.get(sku, {}).get(bin_name, 0)
        if available < quantity:
            raise InventoryError(
                f"cannot remove {quantity} of {sku!r} from {bin_name!r}: "
                f"only {available} available"
            )
        self._stock[sku][bin_name] -= quantity
        if self._stock[sku][bin_name] == 0:
            del self._stock[sku][bin_name]
        if not self._stock[sku]:
            del self._stock[sku]

    def quantity_in_bin(self, sku: str, bin_name: str) -> int:
        """Return how many units of ``sku`` are in ``bin_name`` (0 if none)."""
        return self._stock.get(sku, {}).get(bin_name, 0)

    def total_quantity(self, sku: str) -> int:
        """Return the total quantity of ``sku`` across all bins."""
        return sum(self._stock.get(sku, {}).values())

    def bins_for(self, sku: str) -> dict[str, int]:
        """Return a copy of the per-bin breakdown for ``sku``."""
        return dict(self._stock.get(sku, {}))

    def skus(self) -> list[str]:
        """Return all SKUs currently tracked (with nonzero stock somewhere)."""
        return sorted(self._stock.keys())

